//! Rust port of dll/tgcx/loader/tgcx_loader.cpp (MOD-2 loader, D15, D16).
//!
//! lua51.dll forwards the original's 128 Lua exports to lua51_real.dll (linker
//! directives generated by build.rs) and loads tgcx.dll from the folder of a ticked TGCX
//! package, found through the -mod= list (last first). With no package ticked it
//! is a plain Lua proxy and says so in Logs\tgcx.log.

// Only the Win32 build has an entry point; host builds run the parsing tests.
#![cfg_attr(not(target_arch = "x86"), allow(dead_code))]

pub mod mods;

use std::ffi::c_void;
use std::ptr::{null, null_mut};

use windows_sys::Win32::Foundation::{
    CloseHandle, ERROR_FILE_NOT_FOUND, FreeLibrary, GENERIC_READ, GENERIC_WRITE, GetLastError, HINSTANCE, HMODULE,
    INVALID_HANDLE_VALUE,
};
use windows_sys::Win32::Globalization::{CP_ACP, MultiByteToWideChar};
use windows_sys::Win32::Storage::FileSystem::{
    CREATE_ALWAYS, CreateDirectoryW, CreateFileW, FILE_SHARE_READ, OPEN_EXISTING, ReadFile, WriteFile,
};
use windows_sys::Win32::System::Environment::GetCommandLineA;
use windows_sys::Win32::System::LibraryLoader::{
    GetModuleFileNameW, GetProcAddress, LOAD_WITH_ALTERED_SEARCH_PATH, LoadLibraryExW,
};
use windows_sys::Win32::System::SystemServices::DLL_PROCESS_ATTACH;

use mods::{MAX_PATH, PACKAGE_SIZE, PATH_SIZE, mod_value, parse_mod_args};

#[cfg(not(test))]
include!(concat!(env!("OUT_DIR"), "/forwards.rs"));

// tools/install_dll.py recognises the loader by this marker; tgcx.dll logs it.
static MARKER: &[u8] = b"TGCX loader MOD-2 0.8.0\0";

// The CRT entry calls DllMain. A #[no_mangle] fn would also be exported, and
// install_dll.py accepts only the original's 128 exports, so the symbol is
// defined here and jumps to an ordinary (unexported) Rust function.
#[cfg(all(not(test), target_arch = "x86"))]
std::arch::global_asm!(
    ".globl \"_DllMain@12\"",
    "\"_DllMain@12\":",
    "jmp {dll_main}",
    dll_main = sym dll_main,
);

extern "system" fn dll_main(_module: HINSTANCE, reason: u32, _reserved: *mut c_void) -> i32 {
    if reason == DLL_PROCESS_ATTACH {
        // SAFETY: plain Win32 calls on buffers owned here; runs once under the loader lock.
        unsafe { attach() };
    }
    1
}

unsafe fn attach() {
    let mut exe = [0u16; MAX_PATH];
    let count = unsafe { GetModuleFileNameW(null_mut(), exe.as_mut_ptr(), MAX_PATH as u32) } as usize;
    if count == 0 || count >= MAX_PATH {
        return;
    }
    let Some(slash) = exe[..count].iter().rposition(|&c| c == u16::from(b'\\')) else { return };
    let directory = &exe[..slash];

    let command_line = unsafe { cstr(GetCommandLineA()) };
    let mut logic: HMODULE = null_mut();
    let mut error = ERROR_FILE_NOT_FOUND;
    for file in parse_mod_args(command_line).into_iter().rev() {
        let Some(folder) = package_folder(directory, file) else { continue };
        let Some(path) = game_path(directory, folder.as_slice(), Some(b"tgcx.dll")) else { continue };
        // A full path: never picks up a tgcx.dll from the search path.
        logic = unsafe { LoadLibraryExW(path.as_ptr(), null_mut(), LOAD_WITH_ALTERED_SEARCH_PATH) };
        if !logic.is_null() {
            break;
        }
        error = unsafe { GetLastError() };
    }
    if logic.is_null() {
        log(directory, "no ticked TGCX package with tgcx.dll in the -mod= list; tgcx.dll not loaded", error);
        return;
    }
    let Some(init) = (unsafe { GetProcAddress(logic, c"tgcx_Init".as_ptr().cast()) }) else {
        let error = unsafe { GetLastError() };
        unsafe { FreeLibrary(logic) };
        log(directory, "tgcx.dll has no tgcx_Init", error);
        return;
    };
    // SAFETY: tgcx.dll exports `int __cdecl tgcx_Init(const char*)`.
    let init: unsafe extern "C" fn(*const u8) -> i32 = unsafe { std::mem::transmute(init) };
    // tgcx.dll logs its own result; it stays loaded either way.
    unsafe { init(MARKER.as_ptr()) };
}

/// The `path` of a ticked .mod whose folder holds a tgcx_package.txt with a
/// `package` line; None for every other mod.
fn package_folder(game: &[u16], file: &[u8]) -> Option<Vec<u8>> {
    let text = read_small(&game_path(game, file, None)?)?;
    let folder = mod_value(&text, "path", PATH_SIZE).filter(|p| !p.is_empty())?.to_vec();
    let package = read_small(&game_path(game, &folder, Some(b"tgcx_package.txt"))?)?;
    mod_value(&package, "package", PACKAGE_SIZE).filter(|p| !p.is_empty())?;
    Some(folder)
}

/// "<game>\<relative>[\<leaf>]", NUL-terminated, slashes turned round. The
/// relative part is in the ANSI code page, as on the command line.
fn game_path(game: &[u16], relative: &[u8], leaf: Option<&[u8]>) -> Option<Vec<u16>> {
    let mut out = game.to_vec();
    for part in std::iter::once(relative).chain(leaf) {
        out.push(u16::from(b'\\'));
        out.extend(ansi_to_wide(part)?.into_iter().map(|c| if c == u16::from(b'/') { u16::from(b'\\') } else { c }));
    }
    out.push(0);
    (out.len() <= MAX_PATH).then_some(out)
}

fn ansi_to_wide(s: &[u8]) -> Option<Vec<u16>> {
    if s.is_empty() {
        return Some(Vec::new());
    }
    let mut wide = vec![0u16; MAX_PATH];
    let n = unsafe { MultiByteToWideChar(CP_ACP, 0, s.as_ptr(), s.len() as i32, wide.as_mut_ptr(), MAX_PATH as i32) };
    if n <= 0 {
        return None;
    }
    wide.truncate(n as usize);
    Some(wide)
}

/// Up to 16 KiB of a small text file, like tgcx_ReadSmall's buffer.
fn read_small(path: &[u16]) -> Option<Vec<u8>> {
    let file = unsafe { CreateFileW(path.as_ptr(), GENERIC_READ, FILE_SHARE_READ, null(), OPEN_EXISTING, 0, null_mut()) };
    if file == INVALID_HANDLE_VALUE {
        return None;
    }
    let mut buffer = vec![0u8; 16383];
    let mut read = 0u32;
    let ok = unsafe { ReadFile(file, buffer.as_mut_ptr(), buffer.len() as u32, &mut read, null_mut()) };
    unsafe { CloseHandle(file) };
    if ok == 0 {
        return None;
    }
    buffer.truncate(read as usize);
    Some(buffer)
}

/// Only written when tgcx.dll never opened the log itself.
fn log(directory: &[u16], text: &str, error: u32) {
    let mut path = directory.to_vec();
    path.extend("\\Logs".encode_utf16());
    let mut dir = path.clone();
    dir.push(0);
    path.extend("\\tgcx.log\0".encode_utf16());
    unsafe { CreateDirectoryW(dir.as_ptr(), null()) };
    let file = unsafe { CreateFileW(path.as_ptr(), GENERIC_WRITE, FILE_SHARE_READ, null(), CREATE_ALWAYS, 0, null_mut()) };
    if file == INVALID_HANDLE_VALUE {
        return;
    }
    let marker = std::str::from_utf8(&MARKER[..MARKER.len() - 1]).unwrap_or_default();
    let mut line = format!("{marker}: {text} (error {error}); Lua forwarding only\r\n").into_bytes();
    line.truncate(511);
    let mut written = 0u32;
    unsafe {
        WriteFile(file, line.as_ptr(), line.len() as u32, &mut written, null_mut());
        CloseHandle(file);
    }
}

/// SAFETY: `p` is null or a NUL-terminated string that outlives the process.
unsafe fn cstr(p: *const u8) -> &'static [u8] {
    if p.is_null() {
        return &[];
    }
    unsafe { std::ffi::CStr::from_ptr(p.cast()) }.to_bytes()
}
